# ---------------------------------------------------------------------------
# 2. Resolve asset_id to live placeholder URLs so the HTML demo looks real.
# ---------------------------------------------------------------------------
def resolve_asset_url(asset_id: str | None) -> str | None:
    if not asset_id:
        return None
    # Generate colorful dummy images dynamically for the demo
    if "logo" in asset_id:
        return "https://placehold.co/120x120/2563eb/white?text=Sprints\nLogo"
    if "device" in asset_id:
        return "https://placehold.co/300x250/f97316/white?text=Your\nDevice"
    if "hacker" in asset_id:
        return "https://placehold.co/200x200/ef4444/white?text=Hacker\nIcon"
    return f"https://placehold.co/200x200/e2e8f0/1e293b?text={asset_id}"
# ---------------------------------------------------------------------------
# 3. Simulate the alignment service's timing injection
# ---------------------------------------------------------------------------
def get_dummy_trigger_time(cue_id: str) -> float:
    # Simulating the WhisperX timing logic
    timings = {
        "c0-logo": 0.2,
        "c0-title": 0.8,
        "c1-device": 0.3,
        "c1-hacker": 1.5,
    }
    return timings.get(cue_id, 0.0)
# ---------------------------------------------------------------------------
# 4. Render Logic
# ---------------------------------------------------------------------------
def render(
    plan: ScenePlan, template_dir: str = None, template_name: str = "template.jinja2"
) -> str:
    if template_dir is None:
        template_dir = str(Path(__file__).parent)
    env = Environment(loader=FileSystemLoader(template_dir), autoescape=True)
    template = env.get_template(template_name)
    # Dump Pydantic model to dict so we can inject dynamic variables
    # without breaking strict Pydantic validation rules.
    plan_dict = plan.model_dump()
    for scene in plan_dict["scenes"]:
        for cue in scene["visual_cues"]:
            # Inject the actual working URL
            cue["asset_url"] = resolve_asset_url(cue.get("asset_id"))
            # Inject the alignment timing
            cue["trigger_time_seconds"] = get_dummy_trigger_time(cue.get("cue_id"))
    return template.render(plan=plan_dict)
